from pathlib import Path
from PIL import Image,ImageDraw
import json,hashlib
B=Path(__file__).resolve().parent;ROOT=B.parents[1];D=B/'fix07';D.mkdir(parents=True,exist_ok=True)
source=B/'fix04/generated.png';south=ROOT.parent/'northwest/r05_c04/native/s01_01.png'
im=Image.open(source).convert('RGB');im.paste(Image.open(south).convert('RGB').crop((0,0,1254,230)),(0,1024))
ImageDraw.Draw(im).rectangle((620,0,1120,1023),fill=(110,110,110))
target=D/'visible-edit-mask-context.png'
if target.exists():raise FileExistsError(target)
im.save(target)
band=B/'fix04/real-south-top230.png'
prompt='''Use case: precise-object-edit. The plain medium-grey rectangle is an EDIT MASK, not part of the scene. Fill only this grey rectangle with the missing existing stone railing and stair continuation. Use the visible authentic bottom edge as the sole geometric anchor. Continue its pale stone railing straight upwards, maintaining EXACTLY the same width, silhouette, left and right inset groove positions. The railing must traverse the whole image from top to bottom without a cap, ornament, bend, bulge, sudden step or sideways offset. Its right outside edge is at x1004 where it meets the preserved lower strip; continue that edge at the same x, NOT wider or narrower. The right inner groove meets at x917. The adjacent pale stone stairs should meet the visible far-right stair fragments and continue into the real bottom reference. Reconstruct the left edge of the rail against the existing pedestal.
Image2 is the real native reference cropped from the southern neighbor. Those exact pixels are already in image1 bottom230rows; preserve them and all remaining non-grey artwork without changing location, color or scale. In particular keep the green carving fragment only at the bottom, and keep the large plain pedestal faces on the left. The grey block must disappear completely. The final image is this same1254x1254 crop with a filled gap, opaque, same bright daylight smooth rounded hand-painted pale-stone finish. No new objects, text, UI, people, watermarks, decorative panel or complete building.'''
p={'prompt':prompt,'referenced_image_paths':[str(target),str(band)],'transparent_background':False}
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
(D/'parameters.json').write_text(json.dumps(p,indent=2),encoding='utf-8');(D/'prompt.txt').write_text(prompt,encoding='utf-8')
(D/'preparation.json').write_text(json.dumps({'source':str(source),'sourceSha256':sha(source),'actualSouthSource':str(south),'actualSouthSha256':sha(south),
'southSourceCrop':[0,0,1254,230],'targetPaste':[0,1024,1254,1254],'editMaskRect':[620,0,1121,1024],'maskOnly':True,
'operation':'Preparation guide only: native context crop/paste and visible neutral edit mask, not artwork; output must be generated by image_gen',
'submittedTarget':str(target),'submittedTargetSha256':sha(target),'sourceResampled':False,'guideGameArt':False,'actualModel':None,'actualQuality':None},indent=2),encoding='utf-8')
